def periods_of(cfg, L):
    A = np.array(cfg).reshape(L, L, L)
    per = []
    for ax in range(3):
        for k in range(1, L + 1):
            if L % k == 0 and np.array_equal(A, np.roll(A, k, axis=ax)):
                per.append(k)
                break
        else:
            per.append(L)
    return tuple(sorted(per))

